class NoSupportingHandlers(RequestError):
    """raised when no handlers can support a request for various reasons"""

    def __init__(self, unsupported_errors: list[UnsupportedRequest], unexpected_errors: list[Exception]):
        self.unsupported_errors = unsupported_errors or []
        self.unexpected_errors = unexpected_errors or []

        # Print a quick summary of the errors
        err_handler_map = {}
        for err in unsupported_errors:
            err_handler_map.setdefault(err.msg, []).append(err.handler.RH_NAME)

        reason_str = ', '.join([f'{msg} ({", ".join(handlers)})' for msg, handlers in err_handler_map.items()])
        if unexpected_errors:
            reason_str = ' + '.join(filter(None, [reason_str, f'{len(unexpected_errors)} unexpected error(s)']))

        err_str = 'Unable to handle request'
        if reason_str:
            err_str += f': {reason_str}'

        super().__init__(msg=err_str)

from yt_dlp.networking.exceptions import NoSupportingHandlers, UnsupportedRequest


class _StubHandler:
    def __init__(self, name):
        self.RH_NAME = name


def _err(msg, handler_name):
    err = UnsupportedRequest(msg=msg)
    err.handler = _StubHandler(handler_name)
    return err


class TestNoSupportingHandlersInitBranchOutcomesQA:
    def test_with_unsupported_only(self):
        e = NoSupportingHandlers(
            unsupported_errors=[_err("Proxy not supported", "UrllibRH")],
            unexpected_errors=[],
        )
        assert isinstance(str(e), str)

    def test_with_unexpected_only(self):
        e = NoSupportingHandlers(
            unsupported_errors=[],
            unexpected_errors=[ValueError("boom")],
        )
        assert isinstance(str(e), str)

    def test_with_two_unsupported_same_msg(self):
        e = NoSupportingHandlers(
            unsupported_errors=[
                _err("Proxy not supported", "UrllibRH"),
                _err("Proxy not supported", "RequestsRH"),
            ],
            unexpected_errors=[],
        )
        assert isinstance(str(e), str)
